export default function EvidenceList({ articles }) {
  return (
    <div className="evidenceList">
      {articles.map((article, index) => (
        <a
          key={article.id}
          href={article.url}
          target="_blank"
          rel="noreferrer"
          className="evidenceCard"
        >
          <span className="evidenceNo">根拠 {index + 1}</span>
          <strong>{article.title}</strong>
          <p>{article.evidence}</p>
          <span className="textLink">noteで調査結果を見る ↗</span>
        </a>
      ))}
    </div>
  );
}
