import { certifications } from "../data/certifications";
import { products } from "../data/products";
import { articles } from "../data/articles";

export function getCertification(slug) {
  const cert = certifications.find((item) => item.slug === slug);
  if (!cert) return null;

  return {
    ...cert,
    products: cert.productIds.map((id) => products[id]).filter(Boolean),
    evidenceArticles: cert.evidenceArticleIds
      .map((id) => articles[id])
      .filter(Boolean),
    nextCertification: certifications.find(
      (item) => item.slug === cert.nextSlug
    )
  };
}

export function getFeaturedCertifications() {
  return certifications.filter((item) => item.featured);
}
