import { notFound } from "next/navigation";
import Header from "../../components/Header";
import ProductCTA from "../../components/ProductCTA";
import EvidenceList from "../../components/EvidenceList";
import CareerAdSlot from "../../components/CareerAdSlot";
import { certifications } from "../../data/certifications";
import { getCertification } from "../../lib/data";

export function generateStaticParams() {
  return certifications.map((cert) => ({ slug: cert.slug }));
}

export async function generateMetadata({ params }) {
  const { slug } = await params;
  const cert = getCertification(slug);
  if (!cert) return {};
  return {
    title: `${cert.name} 最短合格`,
    description: `${cert.name}を最短で取るための教材・勉強順・根拠noteを1ページにまとめました。`
  };
}

export default async function CertificationPage({ params }) {
  const { slug } = await params;
  const cert = getCertification(slug);
  if (!cert) notFound();

  return (
    <main>
      <Header />

      <section className="detailHero shell">
        <a className="backLink" href="/">← 資格一覧</a>
        <span className="micro">{cert.category} / SHORTEST ROUTE</span>
        <h1>{cert.name}<br />最短合格</h1>

        <div className="quickFacts">
          <div>
            <span>最短目安</span>
            <strong>{cert.shortestLabel}</strong>
          </div>
          <div>
            <span>勉強時間</span>
            <strong>{cert.studyHoursLabel}</strong>
          </div>
        </div>
      </section>

      <section className="shell section">
        <div className="answerBox">
          <span className="micro">結論</span>
          <h2>迷ったら、この順番。</h2>
          <p>{cert.conclusion}</p>
        </div>
      </section>

      <section className="shell section">
        <div className="sectionTitle">
          <div>
            <span className="micro">EVIDENCE</span>
            <h2>なぜこのルートなのか</h2>
          </div>
          <p>根拠はnoteの調査記事に分離。サイト側で長文を書かない。</p>
        </div>
        <EvidenceList articles={cert.evidenceArticles} />
      </section>

      <section className="shell section">
        <div className="sectionTitle">
          <div>
            <span className="micro">ROADMAP</span>
            <h2>使う教材はこれだけ</h2>
          </div>
          <p>教材を増やしすぎない。</p>
        </div>

        <div className="roadmap">
          {cert.products.map((product, index) => (
            <ProductCTA key={product.id} product={product} index={index} />
          ))}

          <article className="productRow">
            <div className="stepNo">
              {String(cert.products.length + 1).padStart(2, "0")}
            </div>
            <div className="productBody">
              <span className="micro">問題演習</span>
              <h3>{cert.practice.name}</h3>
              <p>{cert.practice.reason}</p>
            </div>
          </article>
        </div>
      </section>

      {cert.nextCertification && (
        <section className="shell section">
          <div className="nextBox">
            <span className="micro">NEXT CERTIFICATION</span>
            <h2>{cert.name}の次は {cert.nextCertification.name}</h2>
            <p>{cert.nextCertification.summary}</p>
            <a className="mainButton" href={`/${cert.nextCertification.slug}`}>
              次の最短ルートを見る →
            </a>
          </div>
        </section>
      )}

      {cert.careerAd && (
        <section className="shell section">
          <CareerAdSlot />
        </section>
      )}

      <section className="shell section">
        <div className="disclosure">
          <strong>PR</strong>
          <p>
            このページにはアフィリエイト広告が含まれています。
            教材・サービスは必要性を確認した上で選択してください。
          </p>
        </div>
      </section>

      <footer className="footer">
        <div className="shell footerInner">
          <a href="/">← 資格一覧</a>
          <span>© 2026 ponpokoken.com</span>
        </div>
      </footer>
    </main>
  );
}
